--
-- Name: generar_qr_code(character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generar_qr_code(lab_code character varying, tipo character varying, numero integer) RETURNS character varying
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN RETURN UPPER(lab_code) || '-' || UPPER(tipo) || '-' || LPAD(numero::TEXT, 3, '0'); END;
$$;


--
-- Name: trigger_set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN NEW.updated_at = NOW(); RETURN NEW; END;
$$;


--
-- Name: validar_correo_utec(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validar_correo_utec(correo character varying) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
BEGIN RETURN correo ~ '^[a-zA-Z0-9.]+@utec\.edu\.pe$'; END;
$_$;


